local CrucibleTongsMaker = {}
local PRODUCTS = {
    iron_crucibletongs = { name = "Železni klešče za crucible", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni klešče za crucible za livarje." },
    bronze_crucibletongs = { name = "Bronast klešče za crucible", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast klešče za crucible za livarje." },
    silver_crucibletongs = { name = "Srebrn klešče za crucible", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn klešče za crucible za livarje." },
    gilded_crucibletongs = { name = "Pozlačen klešče za crucible", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen klešče za crucible za livarje." },
    jewel_set_crucibletongs = { name = "Draguljast klešče za crucible", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast klešče za crucible za livarje." },
    royal_sovereign_crucibletongs = { name = "Kraljevski suveren klešče za crucible", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren klešče za crucible z biseri za krono." },
}
local BUILDINGS = {
    crucibletongs_workshop = { name = "Crucibletongs delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    crucibletongs_house = { name = "Crucibletongs hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_crucibletongs_atelier = { name = "Mojstrski crucibletongs atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_crucibletongs_palace = { name = "Suverena crucibletongs palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
CrucibleTongsMaker.ironStock=18; CrucibleTongsMaker.bronzeStock=14; CrucibleTongsMaker.woodStock=10; CrucibleTongsMaker.leatherStock=8; CrucibleTongsMaker.silverStock=8; CrucibleTongsMaker.goldStock=6; CrucibleTongsMaker.jewelStock=4; CrucibleTongsMaker.pearlStock=4
CrucibleTongsMaker.productStock = {}; CrucibleTongsMaker.buildings = {}; CrucibleTongsMaker.maker = nil; CrucibleTongsMaker.activeMaking = {}; CrucibleTongsMaker.totalProducts = 0; CrucibleTongsMaker.dayTimer = 0
function CrucibleTongsMaker.init() CrucibleTongsMaker.ironStock=18; CrucibleTongsMaker.bronzeStock=14; CrucibleTongsMaker.woodStock=10; CrucibleTongsMaker.leatherStock=8; CrucibleTongsMaker.silverStock=8; CrucibleTongsMaker.goldStock=6; CrucibleTongsMaker.jewelStock=4; CrucibleTongsMaker.pearlStock=4; CrucibleTongsMaker.productStock={}; CrucibleTongsMaker.buildings={}; CrucibleTongsMaker.maker=nil; CrucibleTongsMaker.activeMaking={}; CrucibleTongsMaker.totalProducts=0; CrucibleTongsMaker.dayTimer=0; print("[CrucibleTongsMaker] Royal Crucible Tongs Maker System initialized (6 products, 4 buildings)") end
function CrucibleTongsMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CrucibleTongsMaker.maker={name=n or ("Kleščar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kleščar najet: %s (spretnost: %d)",CrucibleTongsMaker.maker.name,s),"success") end; return true end
function CrucibleTongsMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CrucibleTongsMaker.build(id) local ok,e=CrucibleTongsMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CrucibleTongsMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CrucibleTongsMaker.getQualityBonus() local b=0; for _,bd in ipairs(CrucibleTongsMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CrucibleTongsMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and CrucibleTongsMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and CrucibleTongsMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and CrucibleTongsMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and CrucibleTongsMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and CrucibleTongsMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CrucibleTongsMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CrucibleTongsMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CrucibleTongsMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CrucibleTongsMaker.buildings==0 then return false,"Potrebna kleščna delavnica" end; if not CrucibleTongsMaker.maker then return false,"Potreben kleščar" end; return true end
function CrucibleTongsMaker.make(pt,qty) qty=qty or 1; local ok,e=CrucibleTongsMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then CrucibleTongsMaker.ironStock=CrucibleTongsMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then CrucibleTongsMaker.bronzeStock=CrucibleTongsMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then CrucibleTongsMaker.woodStock=CrucibleTongsMaker.woodStock-d.woodCost*qty end; if d.leatherCost then CrucibleTongsMaker.leatherStock=CrucibleTongsMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then CrucibleTongsMaker.silverStock=CrucibleTongsMaker.silverStock-d.silverCost*qty end; if d.goldCost then CrucibleTongsMaker.goldStock=CrucibleTongsMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CrucibleTongsMaker.jewelStock=CrucibleTongsMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CrucibleTongsMaker.pearlStock=CrucibleTongsMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CrucibleTongsMaker.maker then t=math.max(1,t-math.floor(CrucibleTongsMaker.maker.skill/13)) end; table.insert(CrucibleTongsMaker.activeMaking,{id="crucibletongs_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CrucibleTongsMaker.completeMaking(m) local q=1.0+(CrucibleTongsMaker.getQualityBonus()/100); if CrucibleTongsMaker.maker then q=q+(CrucibleTongsMaker.maker.skill/140) end; q=math.min(2.5,q); CrucibleTongsMaker.productStock[m.productType]=(CrucibleTongsMaker.productStock[m.productType] or 0)+m.quantity; CrucibleTongsMaker.totalProducts=CrucibleTongsMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CrucibleTongsMaker.maker then CrucibleTongsMaker.maker.itemsMade=CrucibleTongsMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then CrucibleTongsMaker.maker.skill=math.min(100,CrucibleTongsMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Klešče izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"crucibletongs.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function CrucibleTongsMaker.update(dt) if not _G.state then return end; CrucibleTongsMaker.dayTimer=CrucibleTongsMaker.dayTimer+dt; if CrucibleTongsMaker.dayTimer>=30 then CrucibleTongsMaker.dayTimer=0; for i=#CrucibleTongsMaker.activeMaking,1,-1 do local m=CrucibleTongsMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CrucibleTongsMaker.completeMaking(m); table.remove(CrucibleTongsMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CrucibleTongsMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CrucibleTongsMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CrucibleTongsMaker.getStats() return {ironStock=CrucibleTongsMaker.ironStock,bronzeStock=CrucibleTongsMaker.bronzeStock,woodStock=CrucibleTongsMaker.woodStock,leatherStock=CrucibleTongsMaker.leatherStock,silverStock=CrucibleTongsMaker.silverStock,goldStock=CrucibleTongsMaker.goldStock,jewelStock=CrucibleTongsMaker.jewelStock,pearlStock=CrucibleTongsMaker.pearlStock,productStock=CrucibleTongsMaker.productStock,numBuildings=#CrucibleTongsMaker.buildings,hasMaker=CrucibleTongsMaker.maker~=nil,makerName=CrucibleTongsMaker.maker and CrucibleTongsMaker.maker.name or "—",makerSkill=CrucibleTongsMaker.maker and CrucibleTongsMaker.maker.skill or 0,activeMaking=#CrucibleTongsMaker.activeMaking,totalProducts=CrucibleTongsMaker.totalProducts} end
return CrucibleTongsMaker
